import React, { createContext, useContext, useState, useEffect } from 'react';

const AuthContext = createContext();

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

export const AuthProvider = ({ children }) => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);
  const [notifications, setNotifications] = useState([]);
  const [adminNotifications, setAdminNotifications] = useState([]);

  useEffect(() => {
    // Check if user is logged in on app start
    const token = localStorage.getItem('token');
    const userData = localStorage.getItem('user');
    
    if (token && userData) {
      setIsAuthenticated(true);
      setUser(JSON.parse(userData));
    }
    
    // Charger les notifications admin depuis localStorage
    const storedAdminNotifications = JSON.parse(localStorage.getItem('adminNotifications') || '[]');
    setAdminNotifications(storedAdminNotifications);
    
    setLoading(false);
  }, []);

  // Polling pour les notifications admin (pour les admins connectés)
  useEffect(() => {
    if (user?.role === 'admin') {
      console.log('🔔 Polling démarré pour admin:', user.name);
      
      const intervalId = setInterval(() => {
        const storedAdminNotifications = JSON.parse(localStorage.getItem('adminNotifications') || '[]');
        console.log('🔔 Polling - Notifications trouvées:', storedAdminNotifications.length);
        
        // Vérifier si les notifications ont changé
        if (JSON.stringify(storedAdminNotifications) !== JSON.stringify(adminNotifications)) {
          console.log('🔔 Polling - Mise à jour des notifications admin');
          setAdminNotifications(storedAdminNotifications);
        }
      }, 1000); // Vérifier toutes les 1 seconde (plus rapide)

      return () => {
        console.log('🔔 Polling arrêté pour admin:', user.name);
        clearInterval(intervalId);
      };
    }
  }, [user?.role, adminNotifications]);

  const login = (userData, token) => {
    setIsAuthenticated(true);
    setUser(userData);
    localStorage.setItem('token', token);
    localStorage.setItem('user', JSON.stringify(userData));
  };

  const logout = () => {
    setIsAuthenticated(false);
    setUser(null);
    setNotifications([]);
    setAdminNotifications([]);
    localStorage.removeItem('token');
    localStorage.removeItem('user');
  };

  const addNotification = (message, type = 'info') => {
    const id = Date.now();
    const newNotification = { id, message, type, timestamp: new Date() };
    setNotifications(prev => [...prev, newNotification]);
  };

  const removeNotification = (id) => {
    setNotifications(prev => prev.filter(notif => notif.id !== id));
  };

  const clearAllNotifications = () => {
    setNotifications([]);
  };

  const notifyAdmins = (message, type = 'info') => {
    const id = Date.now();
    const newAdminNotification = { 
      id, 
      message, 
      type, 
      timestamp: new Date(),
      isAdminNotification: true 
    };
    
    console.log('🔔 notifyAdmins appelé:', message, type);
    console.log('🔔 Utilisateur actuel:', user?.name, 'Role:', user?.role);
    
    // Récupérer les notifications admin existantes depuis localStorage
    const existingAdminNotifications = JSON.parse(localStorage.getItem('adminNotifications') || '[]');
    console.log('🔔 Notifications admin existantes:', existingAdminNotifications.length);
    
    const updatedAdminNotifications = [...existingAdminNotifications, newAdminNotification];
    
    // Sauvegarder dans localStorage (global pour tous les admins)
    localStorage.setItem('adminNotifications', JSON.stringify(updatedAdminNotifications));
    console.log('🔔 localStorage mis à jour avec:', updatedAdminNotifications.length, 'notifications');
    
    // Mettre à jour l'état local si l'utilisateur actuel est admin
    // (pour qu'il voie immédiatement la notification s'il est connecté)
    if (user?.role === 'admin') {
      console.log('🔔 Mise à jour immédiate pour admin connecté');
      setAdminNotifications(updatedAdminNotifications);
    } else {
      console.log('🔔 Utilisateur non-admin, notification sauvegardée pour polling');
    }
    
    console.log('🔔 adminNotifications sauvegardées globalement:', updatedAdminNotifications);
  };

  const removeAdminNotification = (id) => {
    // Récupérer depuis localStorage
    const existingAdminNotifications = JSON.parse(localStorage.getItem('adminNotifications') || '[]');
    const updatedAdminNotifications = existingAdminNotifications.filter(notif => notif.id !== id);
    
    // Sauvegarder dans localStorage
    localStorage.setItem('adminNotifications', JSON.stringify(updatedAdminNotifications));
    
    // Mettre à jour l'état local
    setAdminNotifications(updatedAdminNotifications);
  };

  const clearAllAdminNotifications = () => {
    // Vider localStorage
    localStorage.removeItem('adminNotifications');
    
    // Mettre à jour l'état local
    setAdminNotifications([]);
  };

  const value = {
    isAuthenticated,
    user,
    login,
    logout,
    loading,
    notifications,
    adminNotifications,
    addNotification,
    removeNotification,
    clearAllNotifications,
    notifyAdmins,
    removeAdminNotification,
    clearAllAdminNotifications
  };

  return (
    <AuthContext.Provider value={value}>
      {!loading && children}
    </AuthContext.Provider>
  );
};
